def is_clean_palindrome(text):
    cleaned = [ch.lower() for ch in text if ch.isalnum()]
    if cleaned[0] != cleaned[-1]:
        return False
    low = 0
    high = len(cleaned) - 1
    while low < high:
        if cleaned[low] != cleaned[high]:
            return False
        low += 1
        high -= 1
    return True
